    "target_company_name": "<The company name provided>",
    "precise_role_title": "<The job title provided>",
    "key_technologies": ["<List of 3-5 core technologies (e.g., 'Kubernetes', 'Python', 'Go')>"],
    "core_responsibilities": ["<List of 3-5 core responsibilities (e.g., 'GTM Strategy', 'Platform Engineering')>"],
    "signal_gap_keywords": ["<List of 3-5 keywords that represent gaps to fill>"],
    "signal_overlap_keywords": ["<List of 3-5 keywords that represent existing strengths>"],
